  node['kira_volley']={'spawn_count':0,'teleport':False,'gather':False,'refill_to_six':False,'participants':'snapshot of currently living escorts at command; each shoots in place if still alive at its release event','zero_survivors':'No escort arrows; do not summon or respawn to execute skill','spread_multiplier':1.5,'spread_reference':'existing approved Kira rain spread before +50%; base radius not authored here','target_tracking':'track before each projectile release, lock after release','landing_indicators':False,'replenishment':'separate ordinary death-replacement flow only'}
