  node['clear_condition']={'udono_combat_defeated':True,'stop_combat_and_pending_spawn_events':True,'terminal_presentation':'scripted fall -> stand -> escape; upper-screen message only, no added labels','stage_complete_event':'on authored escape sequence completion; save combat-resolved state immediately, never require hitting fleeing boss','missing_animation_policy':'Integration blocker: author/confirm terminal playback signal before shipping. For isolated logic tests, explicit test harness completion event may substitute; never silent gameplay timeout.','props_required':False,'background_soldiers_required':False,'reinforcement_required':False}
